from mod import resolve, set_at
class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(resolve({'a': {'b': [10, 20]}}, '/a/b/1'), 20)
        self.assertEqual(resolve({'a/b': 1}, '/a~1b'), 1)
